import {createEvidenceUI} from './evidence.js';
import {today,money,accountName} from './domain.js';
import {taskStatus,taskStatusLabel,tasks,metrics,remaining,paid,lineRemaining,stockBalance,provisionalStock,margin,paymentUsed,globalResults,typeLabel,statusLabel,tone,confirmedAmount,orderMismatch} from './erp-domain.js';

export function createERP(ctx){
 const {esc,field,select,area,modal,dialog,table,badge,empty,pageHead,searchBox,match,toast,render,query}=ctx;
 const s=()=>ctx.state(),run=(action,data)=>ctx.run('erp.'+action,data),find=(kind,id)=>s()[kind].find(r=>r.id===id);
 const mobile=()=>!!ctx.isMobile?.();
 const historyViews=new Map();
 let preview='',showInactive=false,tradeFilter='all',taskFilter='all',cashFilter='all',searchText='',visibleTaskIds=[],visibleProductIds=[];
 const selectedTaskIds=new Set();
 const selectedProductIds=new Set();
 const button=(label,action,id='',style='')=>`<button type="button" class="button ${style}" data-action="erp-${action}" data-id="${esc(id)}">${label}</button>`;
 const link=(label,href,style='')=>`<a class="button ${style}" href="${esc(href)}">${esc(label)}</a>`;
 const account=id=>esc(accountName(s(),id));
 const accounts=(current='')=>[['','선택해 주세요'],...s().accounts.filter(a=>a.active!==false||a.id===current).map(a=>[a.id,a.name])];
 const totals=v=>`<div class="workflow-totals"><span>공급가액 <strong>${money(v.net)}</strong></span><span>부가세 <strong>${money(v.vat)}</strong></span><span>합계 <strong>${money(v.amount??v.net+v.vat)}</strong></span></div>`;
 const wide=(title,body,submit,fn)=>{modal(title,body,submit,fn);dialog.classList.add('wide');};
 const evidence=createEvidenceUI({...ctx,money},s,run,button);
 const chip=(label,color)=>`<span class="erp-chip ${color}">${esc(label)}</span>`;
 const tradeStatus=v=>chip(statusLabel[v.status],v.status==='draft'?'orange':v.status==='void'?'grey':'blue');
 const taskRows=items=>items.length?items.map(t=>`<a class="todo-row ${t.tone}" href="${esc(t.href)}"><span class="todo-marker"></span><span class="todo-body"><strong>${esc(t.title)}</strong><small>${esc(t.category)}${t.manual?' · '+taskStatusLabel[taskStatus(t)]:mobile()?' · 자동 · PC에서 처리':''} · ${account(t.accountId)}</small></span><span class="todo-date">${esc(t.dueDate)}<small>${esc(t.dueLabel)}${t.amount?' · '+money(t.amount):''}</small></span><span aria-hidden="true">↗</span></a>`).join(''):empty('해당 할 일이 없어요.');
 const selectableTaskRows=items=>items.length?items.map(t=>{const taskId=t.manual?t.sourceId:'',checked=taskId&&selectedTaskIds.has(taskId);return `<div class="todo-row selectable-task-row ${t.tone} ${checked?'selected':''}"><label class="task-checkbox ${taskId?'':'disabled'}" title="${taskId?'선택':'자동 할 일은 연결된 원거래에서 처리해 주세요.'}"><input type="checkbox" ${taskId?`data-task-checkbox="${esc(taskId)}"`:'disabled'} ${checked?'checked':''} aria-label="${esc(t.title)} 선택"><span aria-hidden="true"></span></label><a class="task-row-content" href="${esc(t.href)}"><span class="todo-marker"></span><span class="todo-body"><strong>${esc(t.title)}</strong><small>${esc(t.category)}${t.manual?' · '+taskStatusLabel[taskStatus(t)]:' · 자동 할 일'} · ${account(t.accountId)}</small></span><span class="todo-date">${esc(t.dueDate)}<small>${esc(t.dueLabel)}${t.amount?' · '+money(t.amount):''}</small></span><span aria-hidden="true">↗</span></a></div>`;}).join(''):empty('해당 할 일이 없어요.');
 const summaryCards=m=>`<div class="erp-kpis"><div><span>이달의 매출 · 확정 전표 / VAT 포함</span><strong>${money(m.sales)}</strong></div><div><span>이달의 지출 · 실제 지급</span><strong>${money(m.outgoing)}</strong></div><div><span>예상 순이익 · 공급 완료 기준</span><strong>${money(m.profit)}</strong><small>${m.reserve===null?'소득세 추정액 미설정':'소득세 추정액 반영'}${m.provisionalCost?' · 재고 기록 부족으로 원가·손익 잠정':''}</small></div></div>`;
 function differencePanel(v,editable=true){
  const diff=orderMismatch(s(),v);if(!diff)return '';
  return `<div class="notice amber order-difference" role="status"><strong>주문과 연결 전표 금액이 다릅니다</strong><p>주문 ${money(diff.orderAmount)} → 전표 ${money(diff.voucherAmount)} · 차이 ${money(diff.difference)} (VAT 포함)</p><p>${v.orderDifferenceReason?'사유: '+esc(v.orderDifferenceReason):'차이 사유 미입력 · 단가, 수량, VAT 선택을 확인해 주세요.'}</p>${editable?button('차이 사유 기록','difference',v.id,'small'):''}</div>`;
 }
 function dashboard(){
  const ts=tasks(s()),due=ts.filter(t=>t.dueDate<=today()),groups=['미수금','지급할 돈','전표 확정','주문·납품','입고 확인','직접 등록'];
  return pageHead('오늘의 업무','오늘 해야 할 일과 놓친 일을 먼저 확인하세요.',button('+ 할 일 등록','task-new','','primary')+link('전체 할 일 보기','#tasks'))+summaryCards(metrics(s(),today().slice(0,7)))+
   `<div class="todo-overview"><a href="#tasks"><strong>${due.filter(t=>t.tone==='red').length}</strong><span>기한이 지난 일</span></a><a href="#tasks"><strong>${due.filter(t=>t.tone==='orange').length}</strong><span>오늘까지 할 일</span></a><a href="#tasks"><strong>${ts.filter(t=>t.tone==='blue').length}</strong><span>예정된 일</span></a></div>`+
   `<div class="erp-task-grid">${groups.map(cat=>{const list=ts.filter(t=>t.category===cat);return `<section class="panel task-panel"><div class="panel-head"><h2>${cat} <span class="count-pill">${list.length}</span></h2><a href="#tasks/${encodeURIComponent(cat)}">모두 보기</a></div>${taskRows(list.slice(0,4))}${list.length>4?`<a class="more-link" href="#tasks/${encodeURIComponent(cat)}">${list.length-4}건 더 보기 →</a>`:''}</section>`;}).join('')}</div><p class="bottom-note">전표 확정은 세금계산서 발행·수취 확인 기록입니다. 납품·입고와 수금·지급은 각각 기록하며, 만기일이 지나고 잔액이 있으면 할 일이 계속 표시됩니다.</p>`;
 }
 function tasksPage(category){
  const selected=category?decodeURIComponent(category):taskFilter,ts=selected==='completed'?s().tasks.filter(t=>taskStatus(t)==='completed').map(t=>({...t,sourceId:t.id,manual:true,category:'직접 등록',href:'#task/'+t.id,dueDate:t.dueDate||t.date,dueLabel:'완료',tone:'grey'})):tasks(s()),list=ts.filter(t=>(selected==='all'||selected==='completed'||t.category===selected)&&match(t.title,accountName(s(),t.accountId)));
  const savedIds=new Set(s().tasks.map(t=>t.id));for(const id of [...selectedTaskIds])if(!savedIds.has(id))selectedTaskIds.delete(id);
  visibleTaskIds=list.filter(t=>t.manual&&t.sourceId).map(t=>t.sourceId);const chosen=[...selectedTaskIds],allVisible=visibleTaskIds.length&&visibleTaskIds.every(id=>selectedTaskIds.has(id));
  const bulkButton=(label,action,style='',disabled=false)=>`<button type="button" class="button ${style}" data-action="erp-${action}" ${disabled?'disabled':''}>${label}</button>`;
  return pageHead('전체 할 일','기한이 지난 일부터 모든 할 일을 확인합니다.',button('+ 할 일 등록','task-new','','primary'))+
   `<div class="toolbar"><div class="tabs" role="group" aria-label="할 일 종류">${['all','미수금','지급할 돈','전표 확정','주문·납품','입고 확인','직접 등록','completed'].map(c=>button(c==='all'?'전체':c==='completed'?'완료한 할 일':c,'task-filter',c,selected===c?'active':'')).join('')}</div>${searchBox('할 일·거래처 검색')}</div><div class="task-bulk-toolbar" role="region" aria-label="선택한 할 일 일괄 처리"><span><strong>${chosen.length}개</strong> 선택</span>${bulkButton(allVisible?'현재 목록 선택 해제':'현재 목록 전체 선택','task-select-all','',!visibleTaskIds.length)}${bulkButton('선택 완료','task-bulk-complete','primary',!chosen.length)}${bulkButton('선택 삭제','task-bulk-delete','danger',!chosen.length)}</div><p class="panel-caption task-bulk-help">체크박스가 있는 직접 등록 할 일만 일괄 처리할 수 있습니다. 자동 할 일은 연결된 전표·주문·수금 상태에서 처리하면 목록에서 자동으로 사라집니다.</p><section class="panel">${selectableTaskRows(list)}</section>`;
 }
 function activity(aid,previous=false){
  const quotes=s().quotes.filter(q=>q.accountId===aid),families=new Map();
  for(const q of quotes){const key=q.familyId||q.id,old=families.get(key);if(!old||(q.version||1)>(old.version||1))families.set(key,q);}
  return [
   ...quotes.filter(q=>previous||families.get(q.familyId||q.id)===q).map(q=>({kind:'quote',date:q.date,label:'견적 · '+q.title,detail:(q.number||'')+' · v'+(q.version||1)+(families.get(q.familyId||q.id)!==q?' · 이전 버전':''),href:'#quote/'+q.id})),
   ...s().orders.filter(o=>o.accountId===aid).map(o=>({kind:'order',date:o.date,label:'주문 · '+o.title,detail:(o.number||o.id)+' · '+o.status,href:'#order/'+o.id})),
   ...s().vouchers.filter(v=>v.accountId===aid).map(v=>({kind:'trade',date:v.date,label:typeLabel[v.kind]+' · '+v.title,detail:v.number+' · '+statusLabel[v.status],href:'#transaction/'+v.id})),
   ...s().payments.filter(p=>p.accountId===aid).map(p=>({kind:'payment',date:p.date,label:(p.direction==='in'?'수금':'지급')+' · '+money(p.amount),detail:(p.status==='void'?'취소':'기록 완료')+(p.memo?' · '+p.memo:''),href:p.allocations?.[0]?'#transaction/'+p.allocations[0].voucherId:'#payments'})),
   ...s().notes.filter(n=>n.accountId===aid).map(n=>({kind:'note',date:n.date,label:'메모 · '+n.body,detail:'',href:'#account/'+aid}))].sort((a,b)=>b.date.localeCompare(a.date));
 }
 const activityRows=rows=>rows.length?rows.map(a=>`<a class="activity-row" href="${esc(a.href)}"><span>${esc(a.label)}${a.detail?`<small>${esc(a.detail)}</small>`:''}</span><time datetime="${esc(a.date)}">${esc(a.date)}</time></a>`).join(''):empty('조건에 맞는 이력이 없어요.');
 const activityHTML=(aid,limit=10)=>activityRows(activity(aid).slice(0,limit));
 function accountHistory(aid){
  const view=historyViews.get(aid)||{kind:'all',previous:false,limit:10};historyViews.set(aid,view);
  const rows=activity(aid,view.previous).filter(a=>view.kind==='all'||a.kind===view.kind);
  return `<section class="panel section-gap account-history" data-account-history><div class="panel-head"><div><h2>거래 이력</h2><p class="panel-caption">${rows.length}건 중 ${Math.min(view.limit,rows.length)}건 · ${view.previous?'이전 견적 버전 포함':'최신 견적 버전 기준'}</p></div>${button(view.previous?'최신 견적만':'이전 견적 버전 포함','history-versions',aid,'small')}</div><div class="history-filters" role="group" aria-label="거래 이력 종류">${[['all','전체'],['quote','견적'],['order','주문'],['trade','거래'],['payment','결제'],['note','메모']].map(([k,label])=>`<button class="button small ${view.kind===k?'active':''}" aria-pressed="${view.kind===k}" data-action="erp-history-filter" data-id="${esc(aid)}" data-kind="${k}">${label}</button>`).join('')}</div>${activityRows(rows.slice(0,view.limit))}<div class="history-pagination">${rows.length>view.limit?button('이력 '+Math.min(20,rows.length-view.limit)+'건 더 보기','history-more',aid):''}${view.limit>10?button('최근 10건으로 접기','history-reset',aid,'small'):''}</div></section>`;
 }
 function accountsPage(){
  const ts=tasks(s()),list=s().accounts.filter(a=>(showInactive||a.active!==false)&&match(a.name,a.contact,a.phone,a.phone2,a.businessNumber)),a=find('accounts',preview);
  if(mobile())return pageHead('거래처','거래처를 검색하고 연락처와 할 일을 확인하세요.')+`<div class="toolbar">${searchBox('거래처·담당자·전화·사업자번호 검색')}${button(showInactive?'활성 거래처만 보기':'비활성 포함','inactive-toggle')}</div><p class="mobile-result-count" role="status">${list.length}개 거래처</p><section class="mobile-account-list" aria-label="거래처 목록">${list.length?list.map(a=>`<a class="mobile-account panel" href="#account/${esc(a.id)}"><div><strong>${esc(a.name)}</strong>${chip(a.active===false?'비활성':a.kind||'고객사',a.active===false?'grey':'blue')}</div><p>${esc(a.contact||'담당자 미등록')} · ${esc(a.phone||a.phone2||'연락처 미등록')}</p><footer><span>할 일 ${ts.filter(t=>t.accountId===a.id).length}건</span><span>상세 보기 →</span></footer></a>`).join(''):empty('검색 결과가 없어요. 검색어 또는 비활성 포함 여부를 확인해 주세요.')}</section>`;
  return pageHead('거래처','거래처를 선택하면 할 일과 최근 거래를 미리 볼 수 있어요.',button('+ 거래처 등록','account-new','','primary'))+
   `<div class="toolbar">${searchBox('거래처·담당자·전화번호 검색')}${button(showInactive?'활성 거래처만 보기':'비활성 포함','inactive-toggle')}</div><div class="account-master ${a?'has-preview':''}"><section class="panel">${table(['거래처명','구분','담당자 / 연락처','할 일','상태','관리'],list.map(a=>`<tr data-action="erp-account-preview" data-id="${esc(a.id)}" tabindex="0" role="button" aria-label="${esc(a.name)} 미리보기" class="clickable-row ${preview===a.id?'selected':''}"><td><strong>${esc(a.name)}</strong></td><td>${esc(a.kind||'고객사')}</td><td>${esc(a.contact||'미등록')}<small>${esc(a.phone||'')}</small></td><td>${ts.filter(t=>t.accountId===a.id).length?chip(ts.filter(t=>t.accountId===a.id).length+'건','orange'):'—'}</td><td>${chip(a.active===false?'비활성':'활성',a.active===false?'grey':'blue')}</td><td><div class="form-actions wrap">${button('수정','account-edit',a.id,'small')}${button('삭제','account-delete',a.id,'small danger')}</div></td></tr>`))}</section>${a?`<aside class="panel account-preview"><div class="panel-head"><h2>${esc(a.name)}</h2>${button('닫기','account-preview','')}</div><div class="form-actions wrap">${link('상세 보기','#account/'+a.id,'primary')}${button('수정','account-edit',a.id)}${button('삭제','account-delete',a.id,'danger')}</div><div class="section-gap">${ts.some(t=>t.accountId===a.id)?taskRows(ts.filter(t=>t.accountId===a.id).slice(0,5)):activityHTML(a.id,5)}</div></aside>`:''}</div>`;
 }
 function accountPage(id){
  const a=find('accounts',id);if(!a)return empty('거래처를 찾을 수 없어요.');const ts=tasks(s()).filter(t=>t.accountId===id),vs=s().vouchers.filter(v=>v.accountId===id&&v.status==='confirmed');
  return pageHead(esc(a.name),'할 일과 견적·주문·거래·결제를 한곳에서 관리합니다.',(mobile()?'':button('정보 수정','account-edit',id)+button('+ 메모','note',id))+button('거래처 삭제','account-delete',id,'danger')+button('+ 할 일','task-new',id,'primary'))+
   `<div class="erp-kpis"><div><span>연락처 1</span><strong class="text-value">${phone(a.phone)}</strong><small>연락처 2 · ${phone(a.phone2)}</small></div><div><span>받을 돈</span><strong>${money(vs.filter(v=>v.kind==='sale').reduce((n,v)=>n+remaining(s(),v),0))}</strong></div><div><span>줄 돈</span><strong>${money(vs.filter(v=>v.kind!=='sale').reduce((n,v)=>n+remaining(s(),v),0))}</strong></div></div><div class="detail-grid"><div class="stack"><section class="panel"><div class="panel-head"><h2>할 일 ${ts.length}건</h2>${chip(a.active===false?'비활성':'활성',a.active===false?'grey':'blue')}</div>${taskRows(ts)}</section></div><section class="panel"><h2>거래처 정보</h2><div class="info-list">${[['담당자',a.contact],['사업자번호',a.businessNumber],['이메일',a.email],['주소',a.address],['기본 결제기한',(a.paymentTermsDays??30)+'일'],['메모',a.notes]].map(([k,v])=>`<div class="info-line"><span>${k}</span><strong>${esc(v||'미등록')}</strong></div>`).join('')}</div><a class="button" href="#quotes">${mobile()?'견적 업무 · PC 이용 안내':'견적 관리'}</a></section></div>${accountHistory(id)}`;
 }
 function phone(value){const number=String(value||'').replace(/[^+0-9]/g,'');return mobile()&&number?`<a href="tel:${esc(number)}">${esc(value)}</a>`:esc(value||'미등록');}
 function accountForm(id){const a=find('accounts',id)||{};wide(a.id?'거래처 수정':'거래처 등록',`<div class="form-grid">${field('상호','name',a.name||'','text','required')}${select('구분','kind',['고객사','매입처','고객사·매입처'],a.kind||'고객사')}${select('활동 상태','active',[['true','active · 활성'],['false','inactive · 비활성']],String(a.active!==false))}${field('기본 결제기한 · 거래일로부터 일수','paymentTermsDays',a.paymentTermsDays??30,'number','min="0" max="365" required')}${field('담당자','contact',a.contact||'')}${field('전화번호 1','phone',a.phone||'')}${field('전화번호 2','phone2',a.phone2||'')}${field('이메일','email',a.email||'','email')}${field('사업자번호','businessNumber',a.businessNumber||'')}${field('대표자','representative',a.representative||'')}${field('주소','address',a.address||'')}${area('메모','notes',a.notes||'')}</div>`,'저장',async f=>{const r=await run('account.save',{...Object.fromEntries(f),id:a.id,active:f.get('active')==='true',paymentTermsDays:Number(f.get('paymentTermsDays'))});preview=r.recordId;toast('거래처를 저장했어요.');});}
 function accountDelete(id){const a=find('accounts',id);if(!a)return;modal('거래처 삭제',`<div class="notice amber">거래처와 연결된 견적·주문·전표·수금·지급·수기 세금자료가 함께 삭제됩니다. 업로드한 원본 파일은 연결만 해제하고 보존합니다. 이 작업은 되돌릴 수 없습니다.</div><p><strong>${esc(a.name)}</strong></p>`,'거래처와 연결 자료 삭제',async()=>{await run('account.delete',{id});preview='';location.hash='#accounts';toast('거래처와 연결 자료를 삭제했어요.');});}
 function taskForm(id,aid=''){const t=find('tasks',id)||{};if(id&&!t.id){toast('직접 등록한 할 일만 수정할 수 있어요. 자동 할 일은 원거래에서 처리해 주세요.');return;}modal(t.id?'할 일 상세·수정':'할 일 등록',`<div class="form-grid">${select('거래처','accountId',accounts(t.accountId||aid),t.accountId||aid)}${field('해야 할 일','title',t.title||'','text','required maxlength="200"')}${field('만기일','date',t.dueDate||t.date||today(),'date','required')}${select('진행 상태','status',Object.entries(taskStatusLabel),t.id?taskStatus(t):'not_started')}${area('상세 내용','notes',t.notes||'')}</div>${t.id?`<div class="task-form-delete">${button('할 일 삭제','task-delete',t.id,'danger')}</div>`:''}`,'저장',async f=>{await run('task.save',{...Object.fromEntries(f),id:t.id});if(location.hash.startsWith('#task/'))location.hash='#tasks';toast('할 일을 저장했어요.');},true);}
 function taskPage(id){const t=find('tasks',id);if(!t)return empty('할 일을 찾을 수 없어요.');return pageHead(esc(t.title),'직접 등록한 할 일',button('할 일 수정·완료','task-edit',id,'primary')+button('할 일 삭제','task-delete',id,'danger')+link('전체 할 일','#tasks'))+`<section class="panel"><div class="transaction-ribbon">${chip(taskStatusLabel[taskStatus(t)],taskStatus(t)==='completed'?'grey':tone(t.dueDate||t.date))}<span>만기 ${esc(t.dueDate||t.date)}</span>${t.accountId?link(accountName(s(),t.accountId),'#account/'+t.accountId):''}</div><p class="workflow-notes">${esc(t.notes||'상세 메모 없음')}</p></section>`;}
 function noteForm(aid){modal('메모 남기기',`<div class="form-grid">${select('거래처','accountId',accounts(aid),aid,'required')}${field('날짜','date',today(),'date','required')}${area('메모','body')}</div>`,'저장',async f=>run('note.save',Object.fromEntries(f)));}
 function productsPage(){
  const list=s().products.filter(p=>match(p.code,p.name,p.spec)),savedIds=new Set(s().products.map(p=>p.id));for(const id of [...selectedProductIds])if(!savedIds.has(id))selectedProductIds.delete(id);
  visibleProductIds=list.map(p=>p.id);const chosen=[...selectedProductIds],allVisible=visibleProductIds.length&&visibleProductIds.every(id=>selectedProductIds.has(id));
  const bulkButton=(label,action,style='',disabled=false)=>`<button type="button" class="button ${style}" data-action="erp-${action}" ${disabled?'disabled':''}>${label}</button>`;
  return pageHead('품목·재고','매입 가격, 판매 가격과 실제 입출고 수량을 관리합니다.',button('+ 품목 등록','product-new','','primary'))+`<div class="toolbar">${searchBox('품목 코드·이름·규격 검색')}</div><div class="quote-bulk-toolbar" role="region" aria-label="선택한 품목 일괄 삭제"><span><strong>${chosen.length}개</strong> 선택</span>${bulkButton(allVisible?'현재 목록 선택 해제':'현재 목록 전체 선택','product-select-all','',!visibleProductIds.length)}${bulkButton('선택 품목 삭제','product-bulk-delete','danger',!chosen.length)}</div><p class="panel-caption quote-bulk-help">품목과 재고 이동 기록이 삭제됩니다. 기존 견적·주문·전표의 품명·규격·금액은 보존됩니다.</p><section class="panel">${list.length?table(['선택','품목 코드 / 품명','규격','매입단가 / 판매단가','재고','재고 평가액','관리'],list.map(p=>{const b=stockBalance(s(),p.id),selected=selectedProductIds.has(p.id);return `<tr class="${selected?'selected':''}"><td><label class="record-checkbox"><input type="checkbox" data-product-checkbox="${esc(p.id)}" ${selected?'checked':''} aria-label="${esc(p.code+' '+p.name)} 선택"></label></td><td><a href="#product/${esc(p.id)}"><strong>${esc(p.code)}</strong><small>${esc(p.name)}</small></a></td><td>${esc(p.spec)}</td><td class="number">${money(p.purchasePrice)}<small>${money(p.salePrice)}</small></td><td>${p.trackStock?chip(b.quantity+' '+p.unit,b.quantity<=p.minStock?'orange':'blue'):chip('서비스','grey')}</td><td class="number">${p.trackStock?money(b.value):'—'}${p.trackStock&&provisionalStock(s(),p.id)?'<small>재고·평가액 참고용</small>':''}</td><td><div class="form-actions wrap">${link('상세','#product/'+p.id,'small')}${button('수정','product-edit',p.id,'small')}${button('삭제','product-delete',p.id,'small danger')}</div></td></tr>`;})):empty('품목을 등록하면 가격표에서 견적에 추가할 수 있어요.')}</section>`;
 }
 function productPage(id){const p=find('products',id);if(!p)return empty('품목을 찾을 수 없어요.');const b=stockBalance(s(),id),moves=s().stockMoves.filter(m=>m.productId===id).slice().reverse(),purchases=s().vouchers.filter(v=>v.kind==='purchase'&&v.items.some(r=>r.productId===id));return pageHead(esc(p.code+' · '+p.name),esc(p.spec),button('품목 수정','product-edit',id)+button('품목 삭제','product-delete',id,'danger')+(!moves.length&&p.trackStock?button('기초재고 등록','opening',id):'')+(p.trackStock?button('재고 사용 기록','stock-use',id):'')+button('매입·입고 등록','purchase-product',id,'primary'))+`<div class="erp-kpis"><div><span>판매단가</span><strong>${money(p.salePrice)}</strong><small>최근 매입단가 ${money(p.purchasePrice)}</small></div><div><span>현재 재고</span><strong>${p.trackStock?b.quantity+' '+esc(p.unit):'서비스'}</strong></div><div><span>이동평균 단가 / 평가액</span><strong>${provisionalStock(s(),id)?'산정 보류':money(b.quantity>0?b.value/b.quantity:0)}</strong><small>${money(b.value)}${provisionalStock(s(),id)?' · 재고 기록 부족 · 잠정 평가액':''}</small></div></div><section class="panel"><h2>입출고 이력</h2>${table(['날짜','구분','수량','금액','연결 전표'],moves.map(m=>{const f=s().fulfillments.find(f=>f.id===m.sourceId||'reverse-'+f.id===m.sourceId),v=f&&find('vouchers',f.voucherId);return `<tr><td>${esc(m.date)}</td><td>${chip(m.quantity>0?'입고':'출고·사용',m.quantity>0?'blue':'orange')}</td><td class="number">${m.quantity}</td><td class="number">${money(m.value)}</td><td>${v?link(v.number,'#transaction/'+v.id,'small'):'기초·사용·정정'}</td></tr>`;}))}</section><section class="panel section-gap"><h2>매입 가격 이력</h2>${table(['거래처','일자','수량','매입단가','상태'],purchases.flatMap(v=>v.items.filter(r=>r.productId===id).map(r=>`<tr><td><a href="#transaction/${esc(v.id)}">${account(v.accountId)}</a></td><td>${esc(v.date)}</td><td>${r.quantity}</td><td>${money(r.unitPrice)}</td><td>${tradeStatus(v)}</td></tr>`)))}</section>`;}
 function productDelete(id){const p=find('products',id);if(!p)return;modal('품목 삭제',`<div class="notice amber">품목과 해당 품목의 재고 이동 기록을 삭제합니다. 기존 견적·주문·전표의 품명·규격·금액 스냅샷은 그대로 남고 품목 연결만 해제됩니다.</div><p><strong>${esc(p.code)} · ${esc(p.name)}</strong><br>${esc(p.spec||'규격 없음')}</p>`,'품목과 재고 이력 삭제',async()=>{await run('product.delete',{id});location.hash='#products';toast('품목과 재고 이력을 삭제했어요.');});}
 function productBulkDelete(){const products=[...selectedProductIds].map(id=>find('products',id)).filter(Boolean);if(!products.length)return;const moveCount=s().stockMoves.filter(m=>selectedProductIds.has(m.productId)).length;modal('선택 품목 일괄 삭제',`<div class="notice amber"><strong>${products.length}개 품목과 재고 이동 ${moveCount}건을 삭제합니다.</strong><br>기존 견적·주문·전표의 품명·규격·금액은 보존되고 품목 연결만 해제됩니다. 이 작업은 되돌릴 수 없습니다.</div><div class="info-list section-gap">${products.slice(0,10).map(p=>`<div class="info-line"><span>${esc(p.code)}</span><strong>${esc(p.name)}</strong></div>`).join('')}${products.length>10?`<p class="panel-caption">외 ${products.length-10}개 품목</p>`:''}</div>`,'선택 품목과 재고 이력 삭제',async()=>{const ids=products.map(p=>p.id);await run('product.bulk-delete',{ids});selectedProductIds.clear();location.hash='#products';toast(`${ids.length}개 품목과 재고 이력을 삭제했어요.`);});}
 function productForm(id){const p=find('products',id)||{};wide('품목 · 가격표',`<div class="form-grid">${field('품목 코드','code',p.code||'','text','required maxlength="80"')}${field('품목명','name',p.name||'','text','required maxlength="140"')}${field('규격','spec',p.spec||'')}${field('단위','unit',p.unit||'EA','text','required')}${field('기준 매입단가 · VAT 제외','purchasePrice',p.purchasePrice||0,'number','min="0" required')}${field('기준 판매단가 · VAT 제외','salePrice',p.salePrice||0,'number','min="0" required')}${select('주 매입처','supplierId',accounts(p.supplierId),p.supplierId||'')}${select('재고 관리','trackStock',[['true','재고 수량 관리'],['false','공임·서비스 · 재고 없음']],String(p.trackStock!==false))}${field('최소 재고','minStock',p.minStock||0,'number','min="0" step="0.001"')}${select('사용 여부','active',[['true','활성'],['false','비활성']],String(p.active!==false))}${area('메모','notes',p.notes||'')}</div>`,'품목 저장',async f=>{const d=Object.fromEntries(f);for(const k of ['salePrice','purchasePrice','minStock'])d[k]=Number(d[k]);d.active=d.active==='true';d.trackStock=d.trackStock==='true';const r=await run('product.save',{...d,id:p.id});location.hash='#product/'+r.recordId;});}
 function stockForm(id,opening){const p=find('products',id);modal(opening?'기초재고 등록':'재고 사용 기록',`<div class="notice">${opening?'이미 보유한 재고만 등록하세요. 신규 구매는 매입 전표의 입고 기록으로 처리합니다.':'납품 출고는 매출 전표의 납품 기록으로 자동 차감됩니다. 여기에는 별도 소모·사용만 기록하세요.'}</div><div class="form-grid">${field('기록일','date',today(),'date','required')}${field('수량','quantity',1,'number','min="0.001" step="0.001" required')}${opening?field('총 재고 평가액 · 공제 VAT 제외','value',p.purchasePrice,'number','min="0" required'):field('사용 목적','reason','','text','required')}</div>`,'저장',async f=>run(opening?'stock.opening':'stock.use',{...Object.fromEntries(f),productId:id,quantity:Number(f.get('quantity')),...opening?{value:Number(f.get('value'))}:{}}));}
 function orderSearch(initial=''){
  return select('관련 고객 주문','orderId',[['','연결하지 않음'],...s().orders.filter(o=>o.status!=='취소'||o.id===initial).map(o=>[o.id,accountName(s(),o.accountId)+' · '+(o.number||o.id)+' · '+o.title])],initial);
 }
 function transactionsPage(){const list=s().vouchers.filter(v=>(tradeFilter==='all'||v.kind===tradeFilter)&&match(v.number,v.title,accountName(s(),v.accountId),v.approvalNumber,...v.items.map(r=>r.name))).slice().sort((a,b)=>b.date.localeCompare(a.date));return pageHead('전체 거래','매출·매입·경비를 같은 기준으로 조회하고 관리합니다.',button('+ 매출','sale-new')+button('+ 매입','purchase-new')+button('+ 경비','expense-new','','primary')+button('개인 인출','withdrawal-new'))+`<div class="toolbar"><div class="tabs" role="group" aria-label="할 일 종류">${['all','sale','purchase','expense','withdrawal'].map(k=>button(k==='all'?'전체':typeLabel[k],'trade-filter',k,tradeFilter===k?'active':'')).join('')}</div>${searchBox('거래처·전표번호·품목·승인번호 검색')}</div><section class="panel">${table(['거래일 / 만기일','구분','거래처 / 내용','전표번호','금액 · VAT 포함','전표 상태','결제 상태'],list.map(v=>{const left=remaining(s(),v);return `<tr><td>${esc(v.date)}<small>만기 ${esc(v.dueDate)}</small></td><td>${chip(typeLabel[v.kind],v.kind==='sale'?'blue':v.kind==='purchase'?'purple':'orange')}</td><td><a href="#transaction/${esc(v.id)}"><strong>${account(v.accountId)}</strong><small>${esc(v.title)}</small></a></td><td><a href="#transaction/${esc(v.id)}">${esc(v.number)}</a></td><td class="number">${money(v.amount)}</td><td>${tradeStatus(v)}</td><td>${v.status==='confirmed'?chip(left?money(left)+' 미결제':'결제 완료',left?tone(v.dueDate):'grey'):'—'}</td></tr>`;}))}</section>`;}
 function voucherForm(kind='sale',id='',productId='',documentId=''){
  const v=find('vouchers',id)||{},p=find('products',productId),doc=find('documents',documentId),ex=doc?.extraction||{};let read;
  const draft=ctx.draft('voucher:'+kind+':'+(id||'new')+':'+productId+':'+documentId);
  const chosenAid=v.accountId||p?.supplierId||s().accounts.find(a=>a.name===ex.accountName)?.id||'';
  const items=v.items?.length?v.items:(v.id?[{name:v.title||'직접 입력',spec:'',unit:'건',quantity:1,unitPrice:v.net||v.amount,vatRate:v.vat?10:0}]:(p?[{productId:p.id,name:p.name,spec:p.spec,unit:p.unit,quantity:1,unitPrice:p.purchasePrice,vatRate:10}]:ex.items?.length?ex.items.map(r=>({...r,vatRate:10})):null));
  wide(typeLabel[kind]+' 전표 '+(v.id?'수정':'등록'),`<div class="notice">초안 저장 후 거래명세서를 확인하고 ‘전표 확정’으로 세금계산서 발행·수취 여부를 기록하세요. 실제 ${kind==='sale'?'납품·작업 완료':'입고'}와 결제는 별도로 기록합니다.</div><div class="form-grid">${select('거래처','accountId',accounts(chosenAid),chosenAid,['sale','purchase'].includes(kind)?'required':'')}${field('거래 내용 · 거래명세서 건명','title',v.title||p?.name||ex.title||'','text','required')}${field('참조 · 거래명세서 표시','attention',v.attention||'')}${field('거래일','date',v.date||ex.date||today(),'date','required')}${field('결제 만기일 · 비우면 거래처 기한 적용','dueDate',v.dueDate||'','date')}${field('전표 확정 할 일 만기일','confirmationDueDate',v.confirmationDueDate||today(),'date','required')}${kind==='expense'||kind==='withdrawal'?select('비용 항목','category',['외주비','월세','차량비','통신비','배송비','자재비','기타 사업 비용','개인 인출'],v.category||(kind==='withdrawal'?'개인 인출':'기타 사업 비용')):''}${kind!=='sale'?select('매입세액 공제','vatDeductible',[['false','공제하지 않음'],['true','공제 대상 확인']],String(v.vatDeductible??(kind==='purchase'))):''}${orderSearch(v.orderId||'')}</div><div data-item-editor class="section-gap"></div><div class="form-grid section-gap">${area('납기·납품 조건','deliveryTerms',v.deliveryTerms||'')}${area('결제 조건','paymentTerms',v.paymentTerms||'')}${area('메모','notes',v.notes||'')}${area('주문과 금액 차이 사유 · 선택','orderDifferenceReason',v.orderDifferenceReason||'')}</div><div class="tax-evidence tax-intro"><span class="tax-label">세무사 증빙용 · 선택 입력</span><p>저장 후 거래 상세의 ‘증빙 정보 편집’에서 작성일·발급일, 과세·공제 구분 등 참고 자료를 입력할 수 있습니다.</p></div>`,'초안 저장',async f=>{const d=Object.fromEntries(f),category=d.category;const r=await run('voucher.save',{...d,kind:category==='개인 인출'?'withdrawal':kind,id:v.id,items:read().map(r=>category==='개인 인출'?{...r,vatRate:0}:r),vatDeductible:category!=='개인 인출'&&d.vatDeductible==='true',documentId:documentId||v.documentId||''});draft.clear();location.hash='#transaction/'+r.recordId;});
  if(v.id&&v.status!=='draft')dialog.querySelector('.notice').textContent='전체 수정으로 저장하면 기존 입출고 이력, 전표 연결 금액, 생성 문서와 수기 세금자료를 정리하고 다시 확정할 수 있는 초안으로 바뀝니다.';
  read=ctx.workflow.editor(draft.items||items,kind==='purchase'?'purchase':'sale');draft.bind(read);
 }
 function activeFulfillments(id){return s().fulfillments.filter(f=>f.voucherId===id&&f.status==='completed');}
 function voucherInfoForm(id){const v=find('vouchers',id),active=activeFulfillments(id),operation=v.kind==='sale'?'납품':'입고';const reason=v.status==='confirmed'?'확정된 금액·품목·거래처는 회계 및 결제 이력 보호를 위해 유지됩니다.':`완료된 ${operation} 이력 ${active.length}건이 연결되어 금액·품목은 잠겨 있습니다. 아래 실제 ${operation} 이력에서 최근 기록부터 취소하면 전체 전표를 다시 수정할 수 있습니다.`;modal('전표 수정',`<div class="notice">${reason} 거래명세서에 표시되는 건명·참조와 거래 조건·메모는 지금 바로 수정할 수 있습니다. 수정 후 PDF·엑셀을 다시 생성하면 변경 내용이 반영됩니다.</div><div class="form-grid">${field('거래 내용 · 거래명세서 건명','title',v.title||'','text','required maxlength="160"')}${field('참조 · 거래명세서 표시','attention',v.attention||'','text','maxlength="500"')}${area('납기·납품 조건','deliveryTerms',v.deliveryTerms||'')}${area('결제 조건','paymentTerms',v.paymentTerms||'')}${area('메모','notes',v.notes||'')}</div>`,'수정 저장',async f=>{await run('voucher.info',{id,...Object.fromEntries(f)});toast('전표 표시 정보를 수정했어요. PDF·엑셀을 다시 생성하면 반영됩니다.');});}
 function voucherDelete(id){const v=find('vouchers',id);modal('전표 삭제',`<div class="notice amber">전표와 연결된 입출고, 전용 수금·지급, 생성 PDF·엑셀, 수기 세금자료를 함께 삭제합니다. 다른 전표와 나누어 연결한 결제는 이 전표 연결액만 해제됩니다. 작업은 되돌릴 수 없습니다.</div><p><strong>${esc(v.number)} · ${esc(typeLabel[v.kind])}</strong><br>${esc(v.title)}</p>`,'전표와 연결 자료 삭제',async()=>{await run('voucher.delete',{id});location.hash='#transactions';toast('전표와 연결 자료를 삭제했어요.');});}
 function transactionPage(id){
  const v=find('vouchers',id);if(!v)return empty('거래를 찾을 수 없어요.');const open=remaining(s(),v),fs=s().fulfillments.filter(f=>f.voucherId===id),activeFs=fs.filter(f=>f.status==='completed'),latestActiveFulfillment=activeFs.at(-1)?.id,ps=s().payments.filter(p=>p.allocations.some(a=>a.voucherId===id)),pending=!v.legacy&&['sale','purchase'].includes(v.kind)&&v.items.some(r=>lineRemaining(s(),v,r)>0),docs=s().documents.filter(d=>d.voucherId===id||(v.sourceDeliveryId&&d.deliveryId===v.sourceDeliveryId)||(v.legacyId&&d.expenseId===v.legacyId)||(v.sourceDocumentId&&d.id===v.sourceDocumentId)),fullEditable=v.status==='draft'&&!activeFs.length;
  const mainAction=v.status==='draft'?'confirm':v.status==='confirmed'&&open?'settle':pending&&v.status!=='void'?'fulfill':v.legacyReviewNeeded?'confirm':'';
  const style=action=>mainAction===action?'primary':'';
  const actions=(v.legacyReviewNeeded?button('이관 전표 확정 확인','confirm',id,style('confirm')):'')+button('전표 전체 수정','voucher-edit',id)+(v.status==='draft'?button('전표 확정','confirm',id,style('confirm')):'')+(v.status==='confirmed'&&open?button(v.kind==='sale'?'수금 기록':'지급 기록','settle',id,style('settle'))+button('기존 선입금·선지급 연결','allocate',id):'')+(pending&&v.status!=='void'?button(v.kind==='sale'?'납품·작업 완료 기록':'입고 기록','fulfill',id,style('fulfill')):'')+button('전표 삭제','voucher-delete',id,'danger');
  const supplied=!v.legacy&&['sale','purchase'].includes(v.kind),supplyLabel=v.status==='void'?'거래 취소':!supplied?'':pending?(fs.some(f=>f.status==='completed')?'일부 '+(v.kind==='sale'?'납품':'입고'):(v.kind==='sale'?'미납품':'미입고')):(v.kind==='sale'?'납품 완료':'입고 완료');
  const collected=paid(s(),v),summary=`<div class="erp-kpis transaction-summary"><div><span>거래 총액 · VAT 포함</span><strong>${money(v.amount)}</strong><small>공급가액 ${money(v.net)} · 부가세 ${money(v.vat)}</small></div><div><span>${v.kind==='sale'?'수금':'지급'}액</span><strong>${money(collected)}</strong><small>${v.status==='confirmed'?(open?(collected?'일부 결제':'미결제'):'결제 완료'):'전표 '+statusLabel[v.status]}</small></div><div><span>${v.status==='confirmed'?'남은 금액':v.status==='void'?'취소된 거래 금액':'확정 전 거래 금액'}</span><strong>${money(v.status==='confirmed'?open:v.amount)}</strong><small>${supplyLabel||(v.legacy?'이관 기록 · 수량 정보 없음':'')}</small></div></div>`;

  const editLock=activeFs.length?`<div class="notice amber">완료된 ${v.kind==='sale'?'납품':'입고'} 이력 ${activeFs.length}건이 연결되어 있습니다. ‘전표 전체 수정’으로 금액·품목을 바꾸면 이 이력과 결제 연결을 정리하고 초안부터 다시 진행합니다.</div>`:'';
  return pageHead(esc(v.number)+' · '+typeLabel[v.kind],esc(v.title),actions)+`<div class="transaction-ribbon">${tradeStatus(v)}${v.status==='confirmed'?chip(open?money(open)+' 미결제':'결제 완료',open?tone(v.dueDate):'grey'):''}<a href="#account/${esc(v.accountId)}">${account(v.accountId)}</a><span>거래일 ${esc(v.date)} · 만기 ${esc(v.dueDate)}</span>${button('기한 수정','voucher-due',id,'small')}</div>`+summary+differencePanel(v)+editLock+(fs.some(f=>f.status==='completed'&&f.costProvisional)?'<p class="notice">납품은 완료되었습니다. 재고 기록 부족으로 출고 원가·손익은 잠정값입니다. 실제 입고를 원래 날짜로 보완하면 다시 계산됩니다.</p>':'')+
   (v.kind==='sale'&&!v.legacy&&v.status==='confirmed'&&pending?'<div class="notice blue">납품 전에 확정한 금액은 선청구로 구분합니다. 실제 납품·작업 완료 수량만 매출손익과 재고 출고에 반영됩니다.</div>':'')+
   `<section class="panel"><div class="panel-head"><h2>거래명세 · 상세 품목</h2><div class="head-actions">${['sale','purchase'].includes(v.kind)?button('PDF 생성','voucher-pdf',id)+button('엑셀 다운로드','voucher-xlsx',id):''}</div></div><div class="info-list"><div class="info-line"><span>건명</span><strong>${esc(v.title)}</strong></div><div class="info-line"><span>참조</span><strong>${esc(v.attention||'미입력')}</strong></div></div>${v.items.length?ctx.workflow.itemTable(v.items):'<p class="panel-caption">이전 장부의 합계 기록입니다. 품목·재고는 추정하지 않았습니다.</p>'}${v.notes?`<p class="workflow-notes">${esc(v.notes)}</p>`:''}${v.orderId?link('연결 주문 보기','#order/'+v.orderId):''}</section>`+
   `<div class="erp-task-grid section-gap" data-operational-history><section class="panel"><h2>수금·지급 이력</h2>${ps.length?table(['실제 결제일','구분','이 전표 연결액','상태','관리'],ps.map(p=>{const allocations=p.allocations.filter(a=>a.voucherId===id),linkedDate=allocations.map(a=>a.date||p.date).sort().at(-1);return `<tr><td>${esc(p.date)}${linkedDate!==p.date?`<small>전표 연결일 ${esc(linkedDate)}</small>`:''}</td><td>${p.direction==='in'?'수금':'지급'}</td><td>${money(allocations.reduce((n,a)=>n+a.amount,0))}</td><td>${p.status==='confirmed'?'기록 완료':'취소'}</td><td><div class="form-actions wrap">${p.status==='confirmed'?button('수정','payment-edit',p.id,'small'):''}${button('삭제','payment-delete',p.id,'small danger')}</div></td></tr>`;})):empty('아직 연결한 결제가 없어요.')}</section><section class="panel"><h2>실제 ${v.kind==='sale'?'납품':'입고'} 이력</h2>${fs.length?table(['일자','수량','상태','관리'],fs.map(f=>`<tr><td>${esc(f.date)}</td><td>${f.items.reduce((n,r)=>n+r.quantity,0)}</td><td>${f.status==='completed'?'완료':'취소'}</td><td><div class="form-actions wrap">${f.status==='completed'?button('수정','fulfillment-edit',f.id,'small'):''}${button('삭제','fulfillment-delete',f.id,'small danger')}</div></td></tr>`)):empty('입출고 이력이 없어요.')}</section></div><section class="panel section-gap"><div class="panel-head"><h2>연결 문서</h2>${button('첨부 문서 연결','document-attach',id)}</div>${docs.map(d=>`<p><a href="/api/documents/${encodeURIComponent(d.id)}/file${query()}&download=1">${esc(d.name)}</a> · ${esc(d.date)}${d.status?` · ${esc(d.status)}`:''}</p>`).join('')||'<p class="panel-caption">생성하거나 연결한 문서가 없습니다.</p>'}</section>${evidence.panel(v)}${v.status!=='void'&&!v.legacy?`<div class="section-gap form-actions wrap">${button('전표 취소','voucher-void',id)}</div>`:''}`;
 }
 function confirmForm(id){const v=find('vouchers',id);modal('전표 확정',`<div class="notice">${typeLabel[v.kind]} ${money(v.amount)}<br>${v.kind==='sale'?'세금계산서 발행':'세금계산서 수취 또는 경비 증빙'} 여부를 확인하고 확정하세요. 승인번호는 확정 후 선택적으로 메모할 수 있습니다.</div><div class="form-grid">${field('전표 확정일 · 증빙 일자','date',v.date,'date','required')}</div>`,'전표 확정',async f=>{await run('voucher.confirm',{id,date:f.get('date')});toast('확정했어요. 국세청 승인번호 버튼에서 메모할 수 있어요.');});}
 function approvalForm(id){const v=find('vouchers',id);modal('국세청 승인번호 메모',`<div class="notice">홈택스에서 실제 발급·수취한 승인번호를 참고용으로 저장합니다. 미입력도 가능하며 국세청에 전송하거나 조회하는 기능은 아닙니다.</div>${field('국세청 승인번호 · 선택','approvalNumber',v.approvalNumber||'','text','maxlength="100"')}`,'메모 저장',async f=>run('voucher.approval',{id,approvalNumber:f.get('approvalNumber')}));}
 function fulfillmentForm(id){const v=find('vouchers',id),rows=v.items.filter(r=>lineRemaining(s(),v,r)>0);wide(v.kind==='sale'?'납품·작업 완료':'매입 입고 기록',`<div class="notice">실제 ${v.kind==='sale'?'납품·작업 완료':'입고'} 날짜와 수량을 입력하세요. 전표 확정일보다 이전 날짜도 가능합니다. 해당 날짜 이후 재고 원가와 손익을 다시 계산합니다.${v.kind==='sale'?' 재고 수량은 참고 정보이며, 부족해도 납품 완료를 기록할 수 있습니다. 부족한 경우 원가·손익은 잠정값으로 표시됩니다.':''}</div>${field('실제 일자','date',today(),'date','required')}<div class="section-gap">${table(['품목','남은 수량','이번 수량'],rows.map((r,i)=>`<tr><td>${esc(r.name)}</td><td>${lineRemaining(s(),v,r)} ${esc(r.unit)}</td><td><input name="qty-${i}" type="number" min="0" max="${lineRemaining(s(),v,r)}" step="0.001" value="${lineRemaining(s(),v,r)}" required></td></tr>`))}</div>`,'완료 기록',async f=>{await run('fulfill',{id,date:f.get('date'),items:rows.map((r,i)=>({lineId:r.id,quantity:Number(f.get('qty-'+i))})).filter(r=>r.quantity>0)});toast('완료 기록을 저장했어요.');});}
 function fulfillmentEditForm(id){const f=find('fulfillments',id),v=f&&find('vouchers',f.voucherId);if(!f||!v)return;const rows=v.items.map(line=>{const old=f.items.find(r=>r.voucherLineId===line.id);return {line,old:old?.quantity||0,max:lineRemaining(s(),v,line)+(old?.quantity||0)};});wide(v.kind==='sale'?'납품 기록 수정':'입고 기록 수정',`<div class="notice">날짜와 수량을 수정하면 관련 재고와 장부 금액을 현재 입력값으로 다시 계산합니다.</div>${field('실제 일자','date',f.date,'date','required')}<div class="section-gap">${table(['품목','최대 수량','수정 수량'],rows.map((r,i)=>`<tr><td>${esc(r.line.name)}</td><td>${r.max} ${esc(r.line.unit)}</td><td><input name="qty-${i}" type="number" min="0" max="${r.max}" step="0.001" value="${r.old}"></td></tr>`))}</div>`,'수정 저장',async form=>{await run('fulfillment.update',{id,date:form.get('date'),items:rows.map((r,i)=>({lineId:r.line.id,quantity:Number(form.get('qty-'+i))})).filter(r=>r.quantity>0)});toast('입출고 기록을 수정했어요.');});}
 function paymentsPage(){const vs=s().vouchers.filter(v=>v.status==='confirmed'&&v.amount>0&&v.kind!=='withdrawal'&&remaining(s(),v)>0&&(cashFilter==='all'||(cashFilter==='in')===(v.kind==='sale'))&&match(v.number,v.title,accountName(s(),v.accountId))).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));const ps=s().payments.filter(p=>p.status==='confirmed'&&p.amount>paymentUsed(p)&&(cashFilter==='all'||p.direction===cashFilter)&&match(accountName(s(),p.accountId),p.memo));return pageHead('수금·지급 관리','받을 돈과 줄 돈, 착수금·선지급을 함께 확인합니다.',button('+ 수금 기록','receipt-new')+button('+ 지급 기록','payment-new','','primary'))+`<div class="toolbar"><div class="tabs">${[['all','전체'],['in','받을 돈'],['out','줄 돈']].map(([k,v])=>button(v,'cash-filter',k,cashFilter===k?'active':'')).join('')}</div>${searchBox()}</div><section class="panel"><h2>미결제 거래</h2>${vs.length?table(['만기일','구분','거래처 / 전표','거래 금액','수금·지급액','남은 금액',''],vs.map(v=>`<tr><td>${chip(v.dueDate,tone(v.dueDate))}</td><td>${v.kind==='sale'?'받을 돈':'줄 돈'}</td><td><a href="#transaction/${esc(v.id)}">${account(v.accountId)}<small>${esc(v.number)} · ${esc(v.title)}</small></a></td><td class="number">${money(v.amount)}</td><td class="number">${money(paid(s(),v))}</td><td class="number"><strong>${money(remaining(s(),v))}</strong></td><td>${button(v.kind==='sale'?'수금':'지급','settle',v.id,'small')}</td></tr>`)):empty('조건에 맞는 미결제 거래가 없어요.')}</section><section class="panel section-gap"><h2>연결하지 않은 선입금·선지급</h2>${ps.length?table(['일자','거래처','구분','남은 금액','메모','관리'],ps.map(p=>`<tr><td>${esc(p.date)}</td><td>${account(p.accountId)}</td><td>${p.direction==='in'?'선수금':'선급금'}</td><td class="number">${money(p.amount-paymentUsed(p))}</td><td>${esc(p.memo)}</td><td><div class="form-actions wrap">${button('수정','payment-edit',p.id,'small')}${button('삭제','payment-delete',p.id,'small danger')}</div></td></tr>`)):empty('조건에 맞는 선입금·선지급이 없어요.')}<p class="panel-caption">해당 거래의 상세 화면에서 ‘기존 선입금·선지급 연결’을 선택하세요.</p></section>`;}
 function paymentForm(direction,voucherId='',paymentId=''){const v=find('vouchers',voucherId),p=find('payments',paymentId);direction=p?.direction||direction;const used=p?paymentUsed(p):0;modal(p?(direction==='in'?'수금 기록 수정':'지급 기록 수정'):(direction==='in'?'수금 기록':'지급 기록'),`<div class="notice">${p?'금액·날짜·메모를 수정하면 장부와 연결 잔액을 다시 계산합니다. 이미 전표에 연결한 '+money(used)+'보다 금액을 작게 줄일 수 없습니다.':'실제 계좌에 들어오거나 나간 금액을 기록합니다. 착수금·잔금은 각각 기록할 수 있습니다.'}</div><div class="form-grid">${select('거래처','accountId',accounts(p?.accountId||v?.accountId),p?.accountId||v?.accountId||'','','required')}${field('실제 결제일','date',p?.date||today(),'date','required')}${field('금액','amount',p?.amount||(v?remaining(s(),v):''),'number',`min="${Math.max(1,used)}" step="1" required`)}${field('메모','memo',p?.memo||'','text','placeholder="착수금 / 잔금 / 자재대금"')}${!v?orderSearch(p?.orderId||''):''}</div>`,'저장',async f=>{await run('payment.save',{...Object.fromEntries(f),id:p?.id||'',direction,amount:Number(f.get('amount')),voucherId:v?.id||''});toast('결제 기록과 잔액을 갱신했어요.');});}
 function deleteRecord(kind,id,label){modal(label+' 삭제',`<div class="notice amber">${label}을 삭제하면 연결 잔액과 장부·재고를 다시 계산합니다. 이 작업은 되돌릴 수 없습니다.</div>`,'삭제',async()=>{await run(kind+'.delete',{id});if(kind==='task'){selectedTaskIds.delete(id);location.hash='#tasks';}toast(label+'을 삭제했어요.');});}
 function bulkTasks(operation){const ids=[...selectedTaskIds];if(!ids.length)return;const completing=operation==='complete',label=completing?'완료 처리':'삭제';modal(`할 일 ${ids.length}개 ${label}`,`<div class="notice ${completing?'blue':'amber'}">선택한 직접 등록 할 일 ${ids.length}개를 ${completing?'완료 상태로 변경합니다.':'삭제합니다. 삭제한 할 일은 되돌릴 수 없습니다.'}</div>`,label,async()=>{await run('task.bulk',{ids,operation});selectedTaskIds.clear();toast(`할 일 ${ids.length}개를 ${completing?'완료 처리':'삭제'}했어요.`);});}
 function allocationForm(id){const v=find('vouchers',id),ps=s().payments.filter(p=>p.status==='confirmed'&&p.accountId===v.accountId&&(p.direction==='in')===(v.kind==='sale')&&p.amount>paymentUsed(p));if(!ps.length)return modal('선입금·선지급 연결',empty('연결 가능한 금액이 없어요.'));modal('선입금·선지급 연결',`<div class="form-grid">${select('결제 내역','id',ps.map(p=>[p.id,p.date+' · '+money(p.amount-paymentUsed(p))+' · '+p.memo]),ps[0].id)}${field('연결 금액','amount',Math.min(remaining(s(),v),ps[0].amount-paymentUsed(ps[0])),'number','min="1" required')}${field('연결일','date',[today(),v.confirmedDate||v.date,ps[0].date].sort().at(-1),'date','required')}</div>`,'연결 저장',async f=>run('payment.allocate',{...Object.fromEntries(f),voucherId:id,amount:Number(f.get('amount'))}));}
 function orderPage(id){const o=find('orders',id);if(!o)return empty('주문을 찾을 수 없어요.');const v=s().vouchers.find(v=>v.orderId===id&&v.kind==='sale'&&v.status!=='void'),m=margin(s(),o),pending=v&&!v.legacy&&v.items.some(r=>lineRemaining(s(),v,r)>0);return pageHead(esc(o.number||o.id),esc(o.title),button('주문 수정','order-edit',id)+button('주문 삭제','order-delete',id,'danger')+button('일정·진행 수정','order-schedule',id)+(pending?button('납품·작업 완료 기록','fulfill',v.id,'primary'):'')+(v?link('연결 매출·거래명세서','#transaction/'+v.id):button('매출 전표·거래명세서 만들기','order-voucher',id,'primary')))+`<div class="transaction-ribbon">${chip(o.orderType==='BOX'?'박스 유통':o.orderType==='DIS'?'분전반':'기존 주문','blue')}${chip(o.status,o.status==='납품 완료'?'grey':'orange')}<a href="#account/${esc(o.accountId)}">${account(o.accountId)}</a><span>납품 예정 ${esc(o.dueDate||'미정')}</span></div>`+totals({net:o.net??Math.round(o.amount/1.1),vat:o.vat??o.amount-Math.round(o.amount/1.1),amount:o.amount})+(v?differencePanel(v):'')+`<section class="panel"><h2>주문 품목</h2>${o.items?.length?ctx.workflow.itemTable(o.items,true):empty('이전 합계 주문입니다. 품목을 입력하면 전표를 만들 수 있어요.',`<button class="button" data-action="wf-order-edit" data-id="${esc(id)}">품목 입력</button>`)}${o.items?.length?`<div class="internal-cost">예상 원가 ${money(m.estimated)} · 예상 마진 ${m.unknown?'마진 산정 불가':money(m.gross)}${m.unknown?' · 원가 미입력 '+m.unknown+'개':''}<br>완료한 납품의 매출 ${money(m.realized)} · 출고 원가·연결 경비 ${money(m.actualCost)}${m.provisionalCost?' · 재고 기록 부족으로 원가·손익 잠정':''}</div>`:'<p class="internal-cost">과거 합계 주문은 품목과 원가를 확인한 뒤 마진을 계산합니다.</p>'}${o.quoteId?link('원본 견적','#quote/'+o.quoteId):''}</section><p class="bottom-note">${o.status==='납품 완료'?'납품을 모두 기록했습니다. 연결 매출에서 결제 상태와 수금 이력을 확인하세요.':'납품 전에도 매출 전표와 거래명세서를 만들고 확정할 수 있습니다. 납품 기록은 연결 매출과 동일하게 반영됩니다.'}</p>`;}
 function analysisPage(){const month=ctx.month(),m=metrics(s(),month),totalsBy=new Map();for(const v of s().vouchers.filter(v=>v.kind==='sale'&&confirmedAmount(v,month)))totalsBy.set(v.accountId,(totalsBy.get(v.accountId)||0)+confirmedAmount(v,month));const ranks=[...totalsBy].filter(([,n])=>n>0).sort((a,b)=>b[1]-a[1]).slice(0,5),[y,mo]=month.split('-').map(Number),months=Array.from({length:6},(_,i)=>{const d=new Date(y,mo-6+i,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;}),ms=months.map(m=>({month:m,...metrics(s(),m)})),max=Math.max(1,...ms.map(m=>Math.max(m.sales,m.outgoing)));
  return pageHead('매출 분석','확정 매출과 실제 공급에 따른 손익, 현금 지출을 나누어 봅니다.',ctx.monthPicker())+summaryCards(m)+`<div class="erp-task-grid"><section class="panel"><h2>월별 매출·지출</h2><div class="bar-chart">${ms.map(r=>`<div class="bar-column"><div class="bar-pair"><div class="sales-bar" style="height:${Math.max(2,r.sales/max*180)}px" title="매출 ${money(r.sales)}"></div><div class="cost-bar" style="height:${Math.max(2,r.outgoing/max*180)}px" title="지출 ${money(r.outgoing)}"></div></div><span>${r.month.slice(5)}월</span></div>`).join('')}</div><p class="panel-caption">파랑: 확정 매출 (VAT 포함) · 주황: 실제 지급</p>${table(['월','매출','지출','예상 순이익'],ms.map(r=>`<tr><td>${r.month}</td><td>${money(r.sales)}</td><td>${money(r.outgoing)}</td><td>${money(r.profit)}</td></tr>`))}</section><section class="panel"><h2>이달의 매출 고객사 Top 5</h2>${table(['순위','고객사','매출액 · VAT 포함'],ranks.map(([id,n],i)=>`<tr><td>${i+1}</td><td><a href="#account/${esc(id)}">${account(id)}</a></td><td class="number">${money(n)}</td></tr>`))}<h2 class="section-gap">손익 계산</h2>${table(['항목','금액'],[['실제 공급 완료 매출 · VAT 제외',m.revenue],['판매 원가와 발생 경비',m.cost],['소득세 추정액',m.reserve],['예상 순이익',m.profit],['납품 전 확정 · 아직 손익 미반영',m.unreceived]].map(([k,v])=>`<tr><td>${k}</td><td class="number">${v===null?'미설정':money(v)}</td></tr>`))}<p class="panel-caption">재고 매입액 전체를 비용으로 빼지 않고, 출고 원가를 비용으로 반영합니다. 과거 이관 자료의 원가·기초재고 누락은 별도 확인이 필요합니다.</p></section></div>`;
 }
 function searchPage(){const results=globalResults(s(),searchText);return pageHead('전체 검색','거래처, 품목, 전표, 견적, 주문을 함께 검색합니다.')+`<section class="panel">${results.length?results.map(r=>`<a class="global-result" href="${esc(r.href)}">${chip(r.type,'blue')}<strong>${esc(r.title)}</strong><small>${esc(r.detail||'')}</small></a>`).join(''):empty(searchText?'검색 결과가 없어요.':'상단 검색창에 검색어를 입력하세요.')}</section>`;}
 function globalSearch(){return `<form class="global-search" data-global-form role="search"><span aria-hidden="true">⌕</span><input data-global-search value="${esc(searchText)}" placeholder="거래처, 품목, 전표 검색" aria-label="전체 검색" autocomplete="off"><button type="submit" aria-label="검색">검색</button></form>`;}
 function pages(route){const [name,id]=route.split('/');const routes={dashboard,accounts:accountsPage,account:()=>accountPage(id),products:productsPage,product:()=>productPage(id),transactions:transactionsPage,transaction:()=>transactionPage(id),tasks:()=>tasksPage(id),payments:paymentsPage,analysis:analysisPage,report:analysisPage,search:searchPage,order:()=>orderPage(id),sales:transactionsPage,expenses:transactionsPage,receivables:paymentsPage,statements:transactionsPage};if(name==='quote'){queueMicrotask(()=>ctx.workflow.quoteDetail(id));return ctx.workflow.quotesPage();}if(name==='task')return taskPage(id);return routes[name]?.();}
 async function exportDoc(kind,id,format){const r=await run('document',{kind,id,format}),d=find('documents',r.documentId);modal(format==='xlsx'?'엑셀 다운로드':'PDF 문서',`<p>${esc(d.name)}</p><div class="form-actions"><a class="button primary" href="/api/documents/${encodeURIComponent(r.documentId)}/file${query()}&download=1" download>다운로드</a><a class="button" href="/api/documents/${encodeURIComponent(r.documentId)}/file${query()}" target="_blank" rel="noopener">열기</a></div>`);}
 function documentAttach(id){
  const docs=s().documents.filter(d=>!d.generated&&!d.quoteId&&(!d.voucherId||d.voucherId===id)&&(!d.expenseId||find('vouchers',id).legacyId===d.expenseId));
  modal('첨부 문서 연결',`<div class="notice">문서함에 올린 거래명세서·세금계산서를 같은 전표에 연결합니다. 거래 금액을 다시 등록하지 않습니다.</div><label class="field">문서 검색<input data-doc-search placeholder="파일명으로 검색"><input type="hidden" name="documentId" required><div class="search-options" data-doc-options></div></label>`,'연결',async f=>run('document.attach',{id,documentId:f.get('documentId')}));
  const input=dialog.querySelector('[data-doc-search]'),options=dialog.querySelector('[data-doc-options]');
  const draw=()=>options.innerHTML=docs.filter(d=>d.name.toLowerCase().includes(input.value.toLowerCase())).slice(0,20).map(d=>`<button type="button" data-doc-choice="${esc(d.id)}">${esc(d.name)}</button>`).join('');
  input.addEventListener('input',()=>{dialog.querySelector('[name="documentId"]').value='';draw();});draw();
  options.addEventListener('click',e=>{const b=e.target.closest('[data-doc-choice]');if(!b)return;dialog.querySelector('[name="documentId"]').value=b.dataset.docChoice;input.value=find('documents',b.dataset.docChoice).name;options.innerHTML='';});
 }
 function cancelForm(entity,id){modal('기록 취소',`<div class="form-grid">${field('취소일','date',today(),'date','required')}${field('취소 사유','reason','','text','required')}</div>`,'취소 기록',async f=>run(entity+'.void',{id,...Object.fromEntries(f)}));}
 async function action(name,id,element){
  const handlers={
   'history-filter':()=>{const view=historyViews.get(id);if(view){view.kind=element?.dataset.kind||'all';view.limit=10;render();}},
   'history-versions':()=>{const view=historyViews.get(id);if(view){view.previous=!view.previous;view.limit=10;render();}},
   'history-more':()=>{const view=historyViews.get(id);if(view){view.limit+=20;render();}},
   'history-reset':()=>{const view=historyViews.get(id);if(view){view.limit=10;render();}},
   'account-new':()=>accountForm(),'account-edit':()=>accountForm(id),'account-delete':()=>accountDelete(id),'account-preview':()=>{preview=id;render();},'inactive-toggle':()=>{showInactive=!showInactive;render();},
   'task-new':()=>taskForm('',id),'task-edit':()=>taskForm(id),'task-delete':()=>deleteRecord('task',id,'할 일'),'task-filter':()=>{taskFilter=id;selectedTaskIds.clear();location.hash='#tasks';render();},'task-select-all':()=>{const allSelected=visibleTaskIds.length&&visibleTaskIds.every(id=>selectedTaskIds.has(id));for(const taskId of visibleTaskIds)allSelected?selectedTaskIds.delete(taskId):selectedTaskIds.add(taskId);render();},'task-bulk-complete':()=>bulkTasks('complete'),'task-bulk-delete':()=>bulkTasks('delete'),note:()=>noteForm(id),
   'product-new':()=>productForm(),'product-edit':()=>productForm(id),'product-delete':()=>productDelete(id),'product-select-all':()=>{const allSelected=visibleProductIds.length&&visibleProductIds.every(id=>selectedProductIds.has(id));for(const productId of visibleProductIds)allSelected?selectedProductIds.delete(productId):selectedProductIds.add(productId);render();},'product-bulk-delete':()=>productBulkDelete(),opening:()=>stockForm(id,true),'stock-use':()=>stockForm(id,false),'purchase-product':()=>voucherForm('purchase','',id),
   'sale-new':()=>voucherForm('sale'),'purchase-new':()=>voucherForm('purchase'),'expense-new':()=>voucherForm('expense'),'withdrawal-new':()=>voucherForm('withdrawal'),'document-purchase':()=>voucherForm('purchase','','',id),'voucher-edit':()=>{const v=find('vouchers',id);return voucherForm(v.kind,id);},'voucher-delete':()=>voucherDelete(id),
   'trade-filter':()=>{tradeFilter=id;render();},'cash-filter':()=>{cashFilter=id;render();},confirm:()=>confirmForm(id),approval:()=>approvalForm(id),fulfill:()=>fulfillmentForm(id),settle:()=>paymentForm(find('vouchers',id).kind==='sale'?'in':'out',id),allocate:()=>allocationForm(id),
   evidence:()=>evidence.form(id),difference:()=>{const v=find('vouchers',id);modal('주문·전표 금액 차이 사유',`${differencePanel(v,false)}${area('차이 사유 · 선택','reason',v.orderDifferenceReason||'')}`,'사유 저장',async f=>run('voucher.difference',{id,reason:f.get('reason')}));},
   'receipt-new':()=>paymentForm('in'),'payment-new':()=>paymentForm('out'),'payment-edit':()=>paymentForm(find('payments',id)?.direction||'in','',id),'payment-delete':()=>deleteRecord('payment',id,'수금·지급 기록'),'fulfillment-edit':()=>fulfillmentEditForm(id),'fulfillment-delete':()=>deleteRecord('fulfillment',id,'입출고 기록'),'voucher-void':()=>cancelForm('voucher',id),'payment-void':()=>cancelForm('payment',id),'fulfillment-void':()=>cancelForm('fulfillment',id),
   'document-attach':()=>documentAttach(id),'voucher-pdf':()=>exportDoc('voucher',id,'pdf'),'voucher-xlsx':()=>exportDoc('voucher',id,'xlsx'),'quote-xlsx':()=>exportDoc('quote',id,'xlsx'),
   'order-edit':()=>ctx.workflow.orderForm(id),'order-delete':()=>ctx.workflow.action('order-delete',id),
   'order-voucher':()=>{const o=find('orders',id);modal('주문에서 매출 전표 생성',`<div class="notice">${esc(o.title)} · 주문 품목과 금액을 가져옵니다. 납품 전에도 생성·확정할 수 있습니다.</div><div class="form-grid">${field('거래일','date',today(),'date','required')}${field('결제 만기일 · 선택','dueDate','','date')}</div>`,'전표 만들기',async f=>{const r=await run('order.voucher',{orderId:id,...Object.fromEntries(f)});location.hash='#transaction/'+r.recordId;});},
   'order-schedule':()=>{const o=find('orders',id);modal('주문 진행·일정',`<div class="form-grid">${field('납품 예정일','dueDate',o.dueDate||'','date')}${select('진행 상태','status',['주문 접수','제작 중'],['주문 접수','제작 중'].includes(o.status)?o.status:'제작 중')}${area('메모','notes',o.notes||'')}</div>`,'저장',async f=>run('order.schedule',{id,...Object.fromEntries(f)}));},
   'voucher-due':()=>{const v=find('vouchers',id);modal('전표 만기일',`<div class="form-grid">${field('결제 만기일','dueDate',v.dueDate,'date','required')}${field('전표 확정 할 일 기한','confirmationDueDate',v.confirmationDueDate||v.date,'date','required')}</div>`,'저장',async f=>run('voucher.schedule',{id,...Object.fromEntries(f)}));}
  };if(handlers[name])await handlers[name]();
 }
 function bind(){
  const form=document.querySelector('[data-global-form]');form?.addEventListener('submit',e=>{e.preventDefault();searchText=form.querySelector('input').value.trim();location.hash='#search';render();});
  document.querySelectorAll('[data-task-checkbox]').forEach(box=>box.addEventListener('change',()=>{box.checked?selectedTaskIds.add(box.dataset.taskCheckbox):selectedTaskIds.delete(box.dataset.taskCheckbox);render();}));
  document.querySelectorAll('[data-product-checkbox]').forEach(box=>box.addEventListener('change',()=>{box.checked?selectedProductIds.add(box.dataset.productCheckbox):selectedProductIds.delete(box.dataset.productCheckbox);render();}));
  document.querySelectorAll('.clickable-row').forEach(row=>row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();action('account-preview',row.dataset.id);}}));
 }
 return {pages,action,globalSearch,bind,orderSearch,voucherForm,accountForm,taskForm};
}
